function Meta({ title, description }: { title: string; description: string }) {
  useEffect(() => {
    const pageTitle = `${title} | IE`;
    document.title = pageTitle;
    const setMeta = (selector: string, attribute: 'name' | 'property', content: string) => {
      let meta = document.head.querySelector<HTMLMetaElement>(selector);
      if (!meta) {
        meta = document.createElement('meta');
        meta.setAttribute(attribute, selector.includes('og:') ? selector.match(/og:[^'"\]]+/)?.[0] ?? '' : selector.match(/name="([^"]+)"/)?.[1] ?? '');
        document.head.appendChild(meta);
      }
      meta.setAttribute('content', content);
    };
    setMeta('meta[name="description"]', 'name', description);
    setMeta('meta[property="og:title"]', 'property', pageTitle);
    setMeta('meta[property="og:description"]', 'property', description);
    setMeta('meta[property="og:url"]', 'property', window.location.href);
    setMeta('meta[name="twitter:title"]', 'name', pageTitle);
    setMeta('meta[name="twitter:description"]', 'name', description);
  }, [title, description]);
  return null;
}

